from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import ClientCaseStudy
from .serializers import ClientCaseStudySummarySerializer

class SimilarCaseStudyView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, case_id):
        case = ClientCaseStudy.objects.filter(id=case_id, organization=request.user.organization).first()
        if not case:
            return Response({"error": "Case study not found"}, status=status.HTTP_404_NOT_FOUND)

        # Explicitly scope similar objects to the same organization
        similar_cases = case.tags.similar_objects().filter(organization=request.user.organization)[:5]
        serializer = ClientCaseStudySummarySerializer(similar_cases, many=True)
        return Response({"case_id": case.id, "similar_cases": serializer.data})
